import logging
from .wts_operations import WTSOperations

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class wts(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    """
    Example of Test cases and Keyword usage:

    .. code-block:: robotframework

        *** Settings ***
        Library    taf.config.wts

        *** Test Cases ***
        Edit WTS config example
            Load Wts Cfg        path/to/original_basic.cfg
            Delete              set PDN_IP="4.7.254.208"
            Modify              set_cell id=1 gnb=2       nr_arfcn=628333:628333
            Modify              set_uec id=1              tgpool=2013265920
            Clone and Modify    set_ue simulated id=1     id=2 imsi=250:555:21645401
            Clone and Modify    ue_param id=1             id=2
            Modify              set_bearer id=2           id=9 ip=4.7.254.208
            Clone and Modify    set_bearer id=9           ue=2 ip=4.7.254.209      after    set_ue id=2
            Insert              set_bearer id=8 ue=1 qci=8   after   set_bearer id=9
            ${imsi}=            Get Parameter             set_ue simulated id=2 imsi=250:555:2164540    imsi
            Log to Console      ${imsi}
            ${pools}=           Get Parameter As List     set_mme id=8 pool=1:1 pool=7:7 pool=3:3  pool  ${True}
            Log to Console      ${pools}
            ${pools}=           Convert Comma Separated String To List  1:1, 2:2, 3:3  ${True}
            Log to Console      ${pools}
            ${pools}=           Create List               1:1  2:2  3:3
            ${pools_csv}=       Convert List Of Strings To Comma Separated String   ${pools}
            Log to Console      ${pools_csv}
            Save Wts Cfg        path/to/new_basic.cfg
            ${commands}=        Find All                  set_cell id=1
            Log to Console      ${commands}
            ${commands}=        Find All By Parameter     pool  id=1
            Log to Console      ${commands}
    """
    def __init__(self, **kwargs):
        super(wts, self).__init__(**kwargs)
        self._wts_operations = WTSOperations()

    def load_wts_cfg(self, file_path):
        """ Load wts.cfg file.
        Data will be stored in volatile memory, loaded file will not be changed
        until `save_wts_cfg` keyword call.

        :param str file_path: path
        """
        return self._wts_operations.load_wts_cfg(file_path)

    def save_wts_cfg(self, file_path=None):
        """ Save all changes, if another path than one during load operation
        given then new file will be created, old one remains without changes.

        :param file_path: path as string
        """
        self._wts_operations.save_wts_cfg(file_path)

    def modify(self, command, modification):
        """ Modify an existing command line. If a non existing parameter is included
            in the modification it will be added

        :param command: command name and one or more parameters to identify
                        uniquely an existing command line
        :param modification: modification requested to the parameters.
        """
        self._wts_operations.modify(command, modification)

    def insert(self, command, location, reference):
        """ insert a new command line

        :param command: command or list of commands and parameters to be inserted
        :param location: location for cloned command relative to the reference
                         after/before
        :param reference: command relative to which the location is considered
        """
        self._wts_operations.insert(command, location, reference)

    def delete(self, command):
        """ Delete all command lines with the command and parameters specified

        :param command: command and one parameter to identify one or more
                        command lines to be deleted
        """
        self._wts_operations.delete(command)

    def get(self, command):
        """ Returns the specified command with all parameters

        :param command: command name and one or more parameters to identify
                        uniquely the command line to be fetched
        """
        return self._wts_operations.get(command)

    def find_all(self, command):
        """
        Find all command lines, which contain the command and parameters specified.

        :param str command: command name only or command name and one or more parameters to identify
                            the command line(s) to be found
        :return: list of found command lines
        :rtype:  list(str)
        """
        return self._wts_operations.find_all(command)

    def find_all_by_parameter(self, parameter, parameter_filter):
        """
        Find all parameter values with given parameter name from any command in wts config file. Certain commands
        with certain other parameter value can be filtered, e.g. find all parameter values of parameter with name 'pool'
        from any command in wts config file which has the 'id=3' parameter set

        :param str parameter:        parameter name to be searched for in wts config file
        :param str parameter_filter: paramter name and value to be filtered for, e.g. id=2
        :return:                     list of command line strings containing the parameter to be searched for
        :rtype:  list(str)
        """
        return self._wts_operations.find_all_by_parameter(parameter, parameter_filter)

    def clone_and_modify(self, command, modification, location=None, reference=None):
        """ Modify an existing command. If a non existing parameter is included
            in the modification it will be added

        :param command: command name and one or more parameters to identify
                        uniquely an existing command
        :param modification: modification requested to the parameters.
        :param location: location for cloned command relative to the reference
                         after/before
        :param reference: command relative to which the location is considered
        """
        self._wts_operations.clone_and_modify(command, modification, location, reference)

    def get_parameter(self, command, parameter):
        """
        Return the parameter value from the first occurrence of a specified command and parameter(s)
        in a command line in WTS config file.

        If more than one parameter contained in command line, one parameter string is returned
        with comma separated values, please refer to get_parameter_as_list also.
        The parameter value of the first occurrence of specified command in WTS config file is returned,
        all other command lines with same command name will be ignored.

        :param str command:   command name and one or more parameters to identify uniquely the command to be fetched
        :param str parameter: parameter name
        :return:          string of parameter value, in case of multiple parameter values a string with
                          comma separated parameter values
        :rtype:           str
        """
        return self._wts_operations.get_parameter(command, parameter)

    def get_parameter_as_list(self, command, parameter):
        """
        Return the parameter value from the first occurrence of a specified command and parameter(s)
        in a command line in WTS config file as a list.

        In case of one parameter is contained in command line a list with one single parameter value is returned.
        In case of more than one parameter with the same name exist in a command line
        a list of parameter values is returned, instead of one parameter containing comma
        separated values as in get_parameter.
        The parameter value list of the first occurrence of specified command in WTS config file is returned,
        all other command lines with same command name will be ignored.

        :param str command:    command name and one or more parameters to identify uniquely the command to be fetched
        :param str parameter:  parameter name
        :return:          list of string with one parameter value, in case of multiple parameters values a list
                          of multiple strings with each parameter value, e.g. command pool="1:1", pool="2:2"
                          returns ['1:1', '2:2']
        :rtype:           list(str)
        """
        return self._wts_operations.get_parameter_as_list(command, parameter)

    @staticmethod
    def convert_comma_separated_string_to_list(comma_separated_string):
        """ Converts a given comma separated string with different values in a string into list of strings with
            a separate string for each value.

        :param comma_separated_string:   given comma separated string with different values
        :return:          list of string with one parameter value in case of no comma given in csv string,
                          in case of multiple parameters separated by comma in csv string values given
                          a list of multiple strings with each parameter value is returned
        :rtype:           list(str)
        """
        return WTSOperations.convert_comma_separated_string_to_list(comma_separated_string)

    @staticmethod
    def convert_list_of_strings_to_comma_separated_string(list_of_strings):
        """ Converts a given list of strings into comma separated string

        :param list_of_strings:  given list of strings with different values
        :return:          a comma separated string which contains all list elements, e.g.
                          given ['abc', 'def', 'ghi'] results in string 'abc, def, ghi'
        :rtype:           str
        """
        return WTSOperations.convert_list_of_strings_to_comma_separated_string(list_of_strings)

    @staticmethod
    def get_parameter_from_command_line_as_list(command, parameter):
        """
        Return the parameter values from a given single command line and given parameter name as a list
        in case of one parameter is contained in command line a list with one single parameter value is returned,
        in case of more than one parameter with the same name exist in a command line
        a list of parameter values is returned.

        :param str command:   command line as it occurs in the WTS config file
        :param str parameter: parameter name
        :return:             list of string with one parameter value, in case of multiple parameters values a list
                             of multiple strings with each parameter value
        :rtype:              list(str)
        """
        return WTSOperations.get_parameter_from_command_line_as_list(command, parameter)
